def feature_controls(prefix):
    options=[(1,'Gradient alignment'),(2,'Auto crop'),(4,'White balance'),(8,'Auto contrast'),(16,'Colour mapping (experimental)')]
    labels=''.join(f'<label for="{prefix}-feature-{bit}"><input id="{prefix}-feature-{bit}" type="checkbox" data-feature="{bit}"><span>{label}</span></label>' for bit,label in options)
    return f'<fieldset class="feature-controls"><legend>Optional features · 可选效果</legend><div class="feature-options">{labels}</div><button type="button" class="reset-features">Reset to original · 恢复原版</button><p class="feature-status" aria-live="polite">Original pyramid NCC · No extra effects</p><details class="feature-details"><summary>Processing details</summary><p class="feature-metadata"></p><a class="crop-diagnostic" target="_blank" rel="noopener">View detected crop rectangle ↗</a><br><a class="baseline-download" target="_blank" rel="noopener">Original full-resolution NCC ↗</a></details></fieldset>'
rows=data['images'];lookup={r['id']:r for r in rows}
fmt=lambda v:f'({v[0]:+d}, {v[1]:+d})'
options=''.join(f'<option value="{r["id"]}" {"selected" if r["id"]=="00458u" else ""}>{r["source"]}</option>' for r in rows)
cards=[]
for r in rows:
    ident=r['id'];p=r['pyramid'];w,h=r['channel_size']
    cards.append(f'''<article class="result-card" data-id="{ident}"><button class="inspect-image" data-inspect="{ident}" aria-label="Inspect {r['source']}"><img src="results/{ident}/aligned.jpg" alt="NCC pyramid reconstruction of {r['source']}" width="600" height="510"><span>COMPARE ↗</span></button><div class="card-caption"><h3>{r['source']}</h3><span>{'HIGH RES' if w>1000 else 'LOW RES'}</span></div><p class="card-dimensions">{w} × {h} px per channel</p><p class="card-offsets">G {fmt(p['green'])} &nbsp; R {fmt(p['red'])}</p><p class="card-timing">{p['seconds']:.3f} s · Full-resolution pyramid</p><a href="results/{ident}/aligned-full.jpg" target="_blank" rel="noopener">Open full-resolution result ↗</a></article>''')
    cards[-1]=cards[-1].replace('<p class="card-dimensions">', feature_controls('card-'+ident)+'<p class="card-dimensions">')
experiments=[]
for ident,title in [('00458u','Fine edges on the locomotive'),('01657u','A portrait at full resolution'),('01728v','When ±15 pixels is not enough')]:
    r=lookup[ident]
    extra='The red vertical shift reaches the single-scale search boundary (+15 px); the pyramid finds +18 px at the original resolution.' if ident=='01728v' else 'The single-scale result is computed on a reduced image; the pyramid refines the offsets on the original pixels. Offsets below use each method’s own resolution.'
    experiments.append(f'''<article class="experiment"><h3>{title}</h3><p class="experiment-id">{r['source']}</p><div class="experiment-pair"><figure><img src="results/{ident}/single.jpg" alt="Single-scale NCC result for {ident}"><figcaption>SINGLE SCALE · {r['single_size'][0]} × {r['single_size'][1]}<br>G {fmt(r['single']['green'])} / R {fmt(r['single']['red'])}</figcaption></figure><figure><img src="results/{ident}/aligned.jpg" alt="Pyramid NCC result for {ident}"><figcaption>PYRAMID · {r['channel_size'][0]} × {r['channel_size'][1]}<br>G {fmt(r['pyramid']['green'])} / R {fmt(r['pyramid']['red'])}</figcaption></figure></div><p>{extra}</p></article>''')
trace_rows=''.join(f'<tr><td>1/{g["scale"]}</td><td>{g["width"]} × {g["height"]}</td><td>±{g["radius"]}</td><td>{fmt(g["offset"])}</td><td>{fmt(r["offset"])}</td></tr>' for g,r in zip(lookup['00458u']['pyramid']['green_trace'],lookup['00458u']['pyramid']['red_trace']))
max_time=max(r['pyramid']['seconds'] for r in rows)
